<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
use Asyura\RotationService;
$site=(string)($_GET['site']??'');$slug=(string)($_GET['slug']??'random-post');$category=trim((string)($_GET['category']??''));$sql='SELECT r.*,s.name site_name,s.url site_url FROM rotation_feeds r JOIN sites s ON s.id=r.site_id WHERE s.public_id=? AND r.slug=? AND r.active=1 AND s.active=1 AND r.category=? LIMIT 1';$stmt=$db->prepare($sql);$stmt->execute([$site,$slug,$category]);$feed=$stmt->fetch();if(!$feed){http_response_code(404);exit('Feed not found');}$item=(new RotationService($db))->item($feed);header('Content-Type: application/rss+xml; charset=utf-8');header('X-Robots-Tag: noindex,follow');echo '<?xml version="1.0" encoding="UTF-8"?>';
?><rss version="2.0" xmlns:media="http://search.yahoo.com/mrss/"><channel><title><?= e($feed['site_name'].' 過去記事') ?></title><link><?= e($feed['site_url']) ?></link><description><?= e($feed['site_name'].'の過去記事再配信RSS') ?></description><lastBuildDate><?= date(DATE_RSS) ?></lastBuildDate><?php if($item): ?><item><title><?= e($item['title']) ?></title><link><?= e($item['url']) ?></link><guid isPermaLink="false"><?= e(hash('sha256',$item['url'].'|'.$feed['current_since'])) ?></guid><pubDate><?= date(DATE_RSS) ?></pubDate><description><![CDATA[<?= str_replace(']]>',']]]]><![CDATA[>',e($item['description'])) ?>]]></description><?php if($item['category']):?><category><?=e($item['category'])?></category><?php endif?><?php if($item['image_url']):?><media:content url="<?=e($item['image_url'])?>" medium="image" /><?php endif?></item><?php endif?></channel></rss>
